const crypto = require('crypto');
const { execution = {}, workflow = {} } = $input.first().json;
const report = {
  executionId: String(execution.id || ('manual-' + Date.now())),
  workflowName: String(workflow.name || 'unknown workflow'),
  nodeName: String(execution.lastNodeExecuted || 'unknown node'),
  message: String((execution.error && execution.error.message) || 'unknown error').slice(0, 400),
};
console.error('[LendLoop workflow error]', JSON.stringify(report));
const body = JSON.stringify(report);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_INBOUND_SECRET).update(timestamp + '.' + body).digest('hex');
return [{ json: { body, timestamp, signature } }];
